import sys

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) < 2:
        return

    a = int(lines[0].strip())
    b = int(lines[1].strip())

    print(f"Addition: {a + b}")
    print(f"Subtraction: {a - b}")
    print(f"Multiplication: {a * b}")
    if b != 0:
        print(f"Division: {a // b}")
    else:
        print("Division: undefined")

if __name__ == "__main__":
    main()
